use rig::image_generation::ImageGenerationRequestBuilder;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.image_generation(openai::GPT_IMAGE_2);


let response = model
    .call(
        ImageGenerationRequestBuilder::new("A futuristic city at sunset")
            .width(1024)
            .height(1024)
            .build(),
    )
    .await?;


std::fs::write("city.png", &response.image)?;

use rig::providers::gemini::{self, Gemini};


let model = Gemini::from_env()?.image_generation(gemini::GEMINI_2_5_FLASH_IMAGE);
let response = model
    .call(ImageGenerationRequestBuilder::new("A flat icon of a banana").build())
    .await?;

use rig::audio_generation::AudioGenerationRequestBuilder;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.audio_generation(openai::TTS_1);


let response = model
    .call(AudioGenerationRequestBuilder::new("Hello, how can I help you today?", "alloy").build())
    .await?;


std::fs::write("hello.mp3", &response.audio)?;

use rig::providers::openai::{self, OpenAI};
use rig::transcription::TranscriptionRequestBuilder;


let model = OpenAI::from_env()?.transcription(openai::WHISPER_1);


let response = model
    .call(
        TranscriptionRequestBuilder::from_file("audio.mp3")?
            .language("en".to_string())
            .build(),
    )
    .await?;


println!("Transcription: {}", response.text);
